import React,{useEffect,useRef,useState} from 'react';
import {collection,getDocs,query,orderBy,limit} from 'firebase/firestore';
import {navigateTo} from './seo';
import {TrustGuide} from './ReleaseTrust';
import './discovery-guide.css';
const customer=[['اختار تخصصك ومنطقتك','ابحث عن الخدمة في المحافظة والمنطقة المناسبة.'],['راجع الملف والأعمال','شوف الصور والمعلومات والتقييمات المنشورة قبل الاتفاق.'],['تواصل واتفق بوضوح','اتصل أو ابعت واتساب، وحدد المطلوب والتكلفة والموعد.'],['شارك تجربتك','بعد التعامل، سجّل الدخول واكتب تقييمًا صادقًا في ملف مقدم الخدمة.']];
const professional=[['أنشئ حسابك','سجّل أو ادخل بحسابك الحالي من زر تسجيل الدخول.'],['كمّل ملفك المهني','أضف تخصصك ومنطقتك ووصفًا واضحًا للخدمات اللي بتقدمها.'],['اعرض شغلك','أضف صور أعمالك ومنشوراتك، وعدّلها لما تحتاج.'],['تابع التواصل','راجع الرسائل وتواصل مع العملاء واتفق على تفاصيل الشغل.']];
export function GuideSteps({onFind,onJoin,compact=false}){return <div className={'discovery-steps'+(compact?' compact':'')}><article><span className="discovery-icon" aria-hidden="true">⌂</span><h2>للعميل</h2><ol>{customer.slice(0,compact?3:4).map(([title,body],i)=><li key={title}><span>{i+1}</span><div><strong>{title}</strong>{!compact&&<p>{body}</p>}</div></li>)}</ol><button onClick={onFind}>دور على مقدم خدمة ←</button></article><article><span className="discovery-icon" aria-hidden="true">⚒</span><h2>للصنايعي والشركات</h2><ol>{professional.slice(0,compact?3:4).map(([title,body],i)=><li key={title}><span>{i+1}</span><div><strong>{title}</strong>{!compact&&<p>{body}</p>}</div></li>)}</ol><button onClick={onJoin}>انضم كمقدم خدمة ←</button></article></div>}
function Agreement(){return <aside className="discovery-agreement"><span aria-hidden="true">◇</span><div><h2>اتفاق واضح يحفظ حقك</h2><p>اتفق كتابةً على الشغل والخامات والسعر والمدة ومراحل الدفع. اسأل مقدم الخدمة عن شروط أي ضمان قبل الاتفاق، واحتفظ بالمحادثات والإيصالات.</p><small>الدليل يعرض الملفات ويسهّل التواصل؛ لا يقدّم ضمان تنفيذ أو ضمانًا تلقائيًا لمدة محددة.</small></div></aside>}
export function HowItWorks({onBack,onFind,onJoin}){return <main className="discovery-page" dir="rtl"><div className="discovery-page-inner"><button className="discovery-back" onClick={onBack}>→ رجوع</button><header><span className="discovery-kicker">خطوات واضحة من أول زيارة</span><h1>طريقة استخدام الدليل الشامل</h1><p>سواء بتدور على خدمة أو عايز تعرض شغلك، ابدأ من هنا.</p></header><GuideSteps onFind={onFind} onJoin={onJoin}/><Agreement/></div></main>}
export default function HomeDiscovery({db,members=[],onFind,onJoin,onRequest,onMemberClick,darkMode}){
 const reviewTrack=useRef(null);
 const scrollReviews=direction=>{const el=reviewTrack.current;if(el)el.scrollBy({left:direction*el.clientWidth*.85,behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});};
 const [reviews,setReviews]=useState([]),[loading,setLoading]=useState(false),[failed,setFailed]=useState(false);
 useEffect(()=>{let live=true;const candidates=members.filter(m=>m.status==='approved'&&Number(m.reviews)>0).slice(0,6);setReviews([]);setFailed(false);if(!candidates.length){setLoading(false);return;}setLoading(true);
 Promise.allSettled(candidates.map(async member=>{const snap=await getDocs(query(collection(db,'members',member.id,'reviews'),orderBy('time','desc'),limit(2)));return snap.docs.map(d=>({...d.data(),id:member.id+'/'+d.id,member}));})).then(results=>{if(!live)return;const rows=results.flatMap(r=>r.status==='fulfilled'?r.value:[]).filter(r=>typeof r.text==='string'&&(r.text.match(/[\p{L}\p{N}]/gu)||[]).length>=3&&r.reviewerId!==r.member.id&&Number.isFinite(Number(r.rating))&&Number(r.rating)>=1&&Number(r.rating)<=5);rows.sort((a,b)=>(b.time?.toMillis?.()||0)-(a.time?.toMillis?.()||0));setReviews(rows.slice(0,6));setFailed(results.some(r=>r.status==='rejected'));setLoading(false);});return()=>{live=false;};
 },[db,members]);
 const shortName=name=>{const words=String(name||'مستخدم').trim().split(/\s+/);return words[0]+(words[1]?' '+words[1][0]+'.':'');};
 return <section className={'discovery-home'+(darkMode?' is-dark':'')} aria-label="تجارب العملاء وطريقة استخدام الدليل" dir="rtl">
 <div className="discovery-join"><div className="discovery-icon" aria-hidden="true">⚒</div><div><strong>شغلك يستاهل يتشاف</strong><p>صنايعي أو صاحب شركة؟ اعرض خدماتك وصور أعمالك.</p></div><button onClick={onJoin}>اعرض شغلك ←</button></div>
 <div className="discovery-story"><div className="discovery-story-copy"><span className="discovery-kicker">◇ اعرف قبل ما تختار</span><h2>اختيارك يبدأ<br/> <em>بتجارب الناس</em></h2><p>راجع الأعمال والتقييمات المنشورة، واتواصل مع مقدم الخدمة اللي يناسبك.</p><div className="discovery-chips"><span>صور أعمال</span><span>تقييمات منشورة</span><span>تواصل مباشر</span></div><button onClick={onFind}>اختار مقدم الخدمة ←</button><button className="discovery-secondary" onClick={onRequest}>محتاج مساعدة في الاختيار؟</button></div>
 <div className="discovery-reviews" aria-label="آراء منشورة على الدليل" aria-busy={loading}>{loading?<div className="discovery-review-empty" role="status">جاري تحميل التقييمات…</div>:reviews.length?<><div className="discovery-review-strip" ref={reviewTrack} tabIndex={0} aria-label="اسحب لعرض المزيد من التقييمات">{reviews.map(r=><article className="discovery-review" key={r.id}><header><span className="discovery-review-avatar" aria-hidden="true">{shortName(r.name)[0]}</span><div><strong>{shortName(r.name)}</strong><small>تقييم على ملف {r.member.name}</small></div></header><div className="discovery-stars" aria-label={`${Number(r.rating)} من 5`}>{'★'.repeat(Math.round(Number(r.rating)))}<span>{'☆'.repeat(5-Math.round(Number(r.rating)))}</span></div><blockquote>{r.text}</blockquote><button onClick={()=>onMemberClick(r.member)}>شوف ملف مقدم الخدمة ←</button></article>)}</div>{reviews.length>1&&<div className="discovery-review-controls"><button type="button" aria-label="التقييم السابق" onClick={()=>scrollReviews(1)}>→</button><span>تجارب الناس على الدليل · اسحب للمزيد</span><button type="button" aria-label="التقييم التالي" onClick={()=>scrollReviews(-1)}>←</button></div>}</>:<div className="discovery-review-empty"><span aria-hidden="true">✦</span><h3>{failed?'التقييمات غير متاحة حاليًا':'كل تجربة تستحق تتسمع'}</h3><p>{failed?'تقدر تراجع تقييمات مقدم الخدمة من ملفه.':'ابدأ بمراجعة صور الأعمال، وبعد التعامل شارك رأيك من ملف مقدم الخدمة.'}</p><button onClick={onFind}>تصفح الملفات والأعمال ←</button></div>}<p className="discovery-review-note">التقييمات آراء أصحابها، ولا تعني أن المنصة تحققت من تنفيذ الخدمة.</p></div></div>
 <section className="discovery-help discovery-help-visible" aria-label="خطوات استخدام الدليل"><div className="discovery-visible-heading"><span className="discovery-kicker">ابدأ من هنا</span><h2>استخدم الدليل في خطوات بسيطة</h2><p>اختار الخطوات المناسبة ليك، وابدأ مباشرة.</p></div><GuideSteps onFind={onFind} onJoin={onJoin} compact/><a className="discovery-full-guide" href="/how-it-works" onClick={event=>{if(event.button===0&&!event.metaKey&&!event.ctrlKey&&!event.shiftKey&&!event.altKey){event.preventDefault();navigateTo("/how-it-works");}}}>شوف شرح الاستخدام كاملًا ←</a><TrustGuide/></section>
 </section>;
}
